export default function MemberBenefitsTable() {
  const [openIndex, setOpenIndex] = useState<number | null>(0);
  const id = useId();
  const t = useTranslations("MembershipBenefits");

  const toggle = (index: number) =>
    setOpenIndex((prev) => (prev === index ? null : index));

  return (
    <section className="mx-auto max-w-7xl px-6 py-12 sm:px-8 sm:py-16">
      <SectionHeading title="Compare Membership Levels" />
      <div
        role="region"
        aria-label="Compare Membership Levels"
        tabIndex={0}
        className="relative overflow-x-auto rounded-2xl border border-white/10 bg-white/[0.025] focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-pink"
      >
        <table className="w-full min-w-[640px] table-fixed border-collapse text-left">
          <caption className="sr-only">Compare Membership Levels</caption>
          <thead>
            <tr className="border-b border-white/10 bg-white/[0.025] text-xs text-grey">
              <th scope="col" className="w-[46%] px-5 py-5 font-medium">
                Benefit Category
              </th>
              {["Strategic", "Enterprise", "Participant"].map((tier) => (
                <th
                  key={tier}
                  scope="col"
                  className="px-2 py-5 text-center font-medium"
                >
                  {tier}
                </th>
              ))}
            </tr>
          </thead>
          {rows.map((row, index) => {
            const isOpen = openIndex === index;
            return (
              <Fragment key={row.title}>
                <tbody>
                  <tr className="border-b border-white/10">
                    <th colSpan={4} scope="rowgroup" className="p-0">
                      <button
                        type="button"
                        aria-expanded={isOpen}
                        aria-controls={`${id}-${index}`}
                        onClick={() => toggle(index)}
                        className="flex min-h-16 w-full items-center justify-between gap-4 px-5 py-4 text-left text-sm font-semibold text-white transition-colors hover:bg-white/5 focus-visible:outline-2 focus-visible:outline-offset-[-2px] focus-visible:outline-pink"
                      >
                        {row.title}
                        <FiPlus
                          aria-hidden="true"
                          size={18}
                          className={`shrink-0 text-[#ff91b7] ${isOpen ? "rotate-45" : ""}`}
                        />
                      </button>
                    </th>
                  </tr>
                </tbody>
                <tbody id={`${id}-${index}`} hidden={!isOpen}>
                  {row.items.map((item, itemIndex) => (
                    <tr
                      key={itemIndex}
                      className="border-b border-white/5 text-sm text-grey odd:bg-white/[0.02]"
                    >
                      <th
                        scope="row"
                        className="px-5 py-4 text-left font-normal leading-relaxed"
                      >
                        <strong className="font-medium text-white">
                          {item.label.bold}
                        </strong>
                        {item.label.rest}
                      </th>
                      {(
                        ["strategic", "enterprise", "participant"] as const
                      ).map((tier) => (
                        <td key={tier} className="px-2 py-4 text-center">
                          {item[tier] ? (
                            <FiCheck
                              className="mx-auto text-[#ff91b7]"
                              size={18}
                              aria-hidden="true"
                            />
                          ) : (
                            <FiMinus
                              className="mx-auto text-white/25"
                              size={16}
                              aria-hidden="true"
                            />
                          )}
                          <span className="sr-only">
                            {t(item[tier] ? "included" : "not-included")}
                          </span>
                        </td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </Fragment>
            );
          })}
        </table>
      </div>
    </section>
  );
}
